package agentskills

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// generatedMarker is the signature substring every AGENTS.md-derived single
// file (GEMINI.md, copilot-instructions.md) carries via generatedNote. `axm
// agents remove` matches on it to distinguish an unmodified generated file from
// a hand-authored one, so removal never clobbers a file the user wrote.
const generatedMarker = "Generated by `axm`"

// generatedNote is prepended to artifacts derived from AGENTS.md so a reader
// (or a future maintainer) knows not to hand-edit the generated copy.
const generatedNote = "<!-- " + generatedMarker + " from the workspace's canonical AGENTS.md + .axiom/skills/. " +
	"Do not edit by hand; re-run `axm agents add %s` after changing the source. -->"

// Single-file artifact layout. The per-skill layout lives on the registry
// (Agent.skillRoot); these are the agents' single, non-per-skill files, shared
// between the plan* emitters and the remove* functions.
const (
	claudeMirrorFile = "CLAUDE.md" // mirror of AGENTS.md for Claude Code
	geminiFile       = "GEMINI.md" // flattened Gemini context file
)

// copilotRootFile is a var (filepath.Join is not a constant expression) but is
// treated as an immutable layout constant.
var copilotRootFile = filepath.Join(".github", "copilot-instructions.md")

// Lossy-conversion warnings surfaced by the flatten emitters. Defined once so
// the emitter and any test that asserts "this agent warns" agree on the text.
const geminiWarning = "Gemini has no on-demand skill mechanism; all skill bodies are inlined into GEMINI.md and always " +
	"in context — progressive disclosure is flattened."

// --- per-agent planners ---------------------------------------------------
//
// A plan* function returns the artifacts an agent would materialize plus any
// lossy-conversion warnings. It writes nothing — applyArtifacts (add/sync) does
// the writing, and PlanChanges/Stale compare the artifacts against disk. This
// one source of truth is what keeps add, sync, dry-run, and staleness in sync.

// planClaude: native SKILL.md per skill (verbatim — the canonical format is
// already Claude's), plus a CLAUDE.md mirror of the AGENTS.md baseline (Claude
// Code does not read AGENTS.md natively).
func planClaude(a Agent, ws string, skills []Skill) ([]Artifact, []string) {
	arts := skillFileArtifacts(a, skills, func(s Skill) string { return s.Raw })
	if base := readAgentsMD(ws); base != "" {
		arts = append(arts, Artifact{Rel: claudeMirrorFile, Content: base, Mirror: true})
	}
	return arts, nil
}

// planCodex: native SKILL.md per skill (verbatim — the Agent Skills path Codex
// reads). Codex reads AGENTS.md natively, so no instruction file is synthesized.
func planCodex(a Agent, _ string, skills []Skill) ([]Artifact, []string) {
	return skillFileArtifacts(a, skills, func(s Skill) string { return s.Raw }), nil
}

// planCursor: a native SKILL.md per skill at .cursor/skills/<name>/SKILL.md.
// Cursor adopted the Anthropic Agent Skills standard, so the canonical SKILL.md
// is emitted verbatim (same as claude/codex) — progressive disclosure is
// preserved, with no lossy transform. Cursor reads AGENTS.md natively for the
// baseline.
func planCursor(a Agent, _ string, skills []Skill) ([]Artifact, []string) {
	return skillFileArtifacts(a, skills, func(s Skill) string { return s.Raw }), nil
}

// planCopilot: a repo-wide copilot-instructions.md from the AGENTS.md baseline
// plus one native SKILL.md per skill at .github/skills/<name>/SKILL.md. VS Code
// Copilot adopted the Anthropic Agent Skills standard, so the canonical SKILL.md
// is emitted verbatim — on-demand progressive disclosure is preserved. The
// repo-wide instructions file stays for always-on project context (it has no
// skill equivalent).
func planCopilot(a Agent, ws string, skills []Skill) ([]Artifact, []string) {
	var arts []Artifact
	if base := readAgentsMD(ws); base != "" {
		arts = append(arts, Artifact{Rel: copilotRootFile, Content: fmt.Sprintf(generatedNote, "copilot") + "\n\n" + base})
	}
	arts = append(arts, skillFileArtifacts(a, skills, func(s Skill) string { return s.Raw })...)
	return arts, nil
}

// planGemini: a single GEMINI.md — a `@AGENTS.md` import for the baseline
// followed by every skill inlined. Gemini has no skill mechanism and loads its
// whole context each prompt, so the bodies are always present.
func planGemini(_ Agent, ws string, skills []Skill) ([]Artifact, []string) {
	var warns []string
	if len(skills) > 0 {
		warns = append(warns, geminiWarning)
	}
	return []Artifact{{Rel: geminiFile, Content: geminiDoc(ws, skills)}}, warns
}

// skillFileArtifacts builds one Artifact per skill at the agent's per-skill
// path, with content from body. It is the shared shape for every per-skill
// emitter (the agents differ only in path layout and content transform).
func skillFileArtifacts(a Agent, skills []Skill, body func(Skill) string) []Artifact {
	arts := make([]Artifact, 0, len(skills))
	for _, s := range skills {
		arts = append(arts, Artifact{Rel: a.skillArtifactRel(s.Name), Content: body(s)})
	}
	return arts
}

// --- content transforms ---------------------------------------------------

// geminiDoc renders the whole flattened GEMINI.md.
func geminiDoc(ws string, skills []Skill) string {
	var b strings.Builder
	b.WriteString("# GEMINI.md — Axiom workspace context\n\n")
	b.WriteString(fmt.Sprintf(generatedNote, "gemini") + "\n\n")
	if readAgentsMD(ws) != "" {
		b.WriteString("@AGENTS.md\n\n")
	}
	if len(skills) > 0 {
		b.WriteString("## Skills\n\n")
		b.WriteString("Gemini has no on-demand skill mechanism, so the workspace skills are inlined below. " +
			"Apply each one when its _use when_ description matches what the user is doing.\n\n")
		for _, s := range skills {
			b.WriteString(fmt.Sprintf("### %s\n\n", s.Name))
			if s.Description != "" {
				b.WriteString(fmt.Sprintf("_Use when:_ %s\n\n", s.Description))
			}
			b.WriteString(strings.TrimRight(stripLeadingH1(s.Body), "\n"))
			b.WriteString("\n\n")
		}
	}
	return b.String()
}

// --- apply ----------------------------------------------------------------

// applyArtifacts writes each artifact to the workspace, returning the
// workspace-relative paths written. It is idempotent: an existing file is
// overwritten, so re-running materialization refreshes artifacts in place.
func applyArtifacts(ws string, arts []Artifact) ([]string, error) {
	var written []string
	for _, art := range arts {
		if art.Mirror {
			rel, err := mirrorAgentsMD(ws, art.Rel)
			if err != nil {
				return written, err
			}
			if rel != "" {
				written = append(written, rel)
			}
			continue
		}
		if err := writeWorkspaceFile(ws, art.Rel, art.Content); err != nil {
			return written, err
		}
		written = append(written, art.Rel)
	}
	return written, nil
}

// --- helpers --------------------------------------------------------------

// writeWorkspaceFile writes content to <ws>/<rel>, creating parent dirs. It is
// idempotent: an existing file is overwritten, so re-running materialization
// refreshes artifacts in place.
func writeWorkspaceFile(ws, rel, content string) error {
	p := filepath.Join(ws, rel)
	if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
		return fmt.Errorf("create dir for %s: %w", rel, err)
	}
	if err := os.WriteFile(p, []byte(content), 0o644); err != nil {
		return fmt.Errorf("write %s: %w", rel, err)
	}
	return nil
}

// readAgentsMD returns the workspace AGENTS.md content, or "" if absent.
func readAgentsMD(ws string) string {
	data, err := os.ReadFile(filepath.Join(ws, "AGENTS.md"))
	if err != nil {
		return ""
	}
	return string(data)
}

// mirrorAgentsMD makes <ws>/<rel> reflect AGENTS.md: a relative symlink when
// the OS allows it (so edits to AGENTS.md stay in sync), falling back to a
// content copy on platforms/filesystems that reject symlinks (e.g. Windows
// without privilege). Returns the written rel path, or "" if there is no
// AGENTS.md to mirror.
func mirrorAgentsMD(ws, rel string) (string, error) {
	src := filepath.Join(ws, "AGENTS.md")
	if _, err := os.Stat(src); err != nil {
		return "", nil
	}
	dst := filepath.Join(ws, rel)
	_ = os.Remove(dst) // idempotent re-materialization
	if err := os.Symlink("AGENTS.md", dst); err == nil {
		return rel, nil
	}
	data, err := os.ReadFile(src)
	if err != nil {
		return "", fmt.Errorf("read AGENTS.md: %w", err)
	}
	if err := os.WriteFile(dst, data, 0o644); err != nil {
		return "", fmt.Errorf("write %s: %w", rel, err)
	}
	return rel, nil
}

// isGeneratedMirror reports whether <ws>/<rel> is still the AGENTS.md mirror axm
// produced: an unmodified relative symlink to this workspace's AGENTS.md, or
// (the symlink-less fallback) a copy byte-identical to it. Used by staleness (an
// unmodified mirror is current) and by removal's keep/clobber decision.
func isGeneratedMirror(ws, rel string) bool {
	p := filepath.Join(ws, rel)
	info, err := os.Lstat(p)
	if err != nil {
		return false
	}
	agentsMD := filepath.Join(ws, "AGENTS.md")
	if info.Mode()&os.ModeSymlink != 0 {
		target, err := os.Readlink(p)
		if err != nil {
			return false
		}
		resolved := target
		if !filepath.IsAbs(resolved) {
			resolved = filepath.Join(filepath.Dir(p), resolved)
		}
		return filepath.Clean(resolved) == filepath.Clean(agentsMD)
	}
	mirror, errM := os.ReadFile(p)
	base, errB := os.ReadFile(agentsMD)
	return errM == nil && errB == nil && string(mirror) == string(base)
}

// stripLeadingH1 drops a leading "# Title" line (and the blank line after it)
// so an inlined skill body does not nest an h1 under the Gemini "###" heading.
func stripLeadingH1(body string) string {
	trimmed := strings.TrimLeft(body, "\n")
	if !strings.HasPrefix(trimmed, "# ") {
		return body
	}
	if nl := strings.IndexByte(trimmed, '\n'); nl >= 0 {
		return strings.TrimLeft(trimmed[nl+1:], "\n")
	}
	return ""
}
